package fable.hideseek.imba.net;
import fable.hideseek.imba.config.BreakRulesConfig;import net.fabricmc.fabric.api.networking.v1.PacketByteBufs;import net.fabricmc.fabric.api.networking.v1.ServerPlayNetworking;import net.minecraft.network.PacketByteBuf;import net.minecraft.registry.Registries;import net.minecraft.server.network.ServerPlayerEntity;import net.minecraft.text.Text;import net.minecraft.util.Identifier;import java.util.Set;
public final class BlockRulesNetworking{public static final Identifier REQUEST=new Identifier("imba","block_rules_request"),SET=new Identifier("imba","block_rules_set_v2"),SYNC=new Identifier("imba","block_rules_sync_v2");private BlockRulesNetworking(){}public static void register(){ServerPlayNetworking.registerGlobalReceiver(REQUEST,(server,player,handler,buf,sender)->server.execute(()->{if(!player.hasPermissionLevel(2)){player.sendMessage(Text.literal("§cДля настройки исключений нужны права оператора"),true);return;}sendSync(player);}));ServerPlayNetworking.registerGlobalReceiver(SET,(server,player,handler,buf,sender)->{int type=buf.readUnsignedByte();String rawId=buf.readString(256);boolean enabled=buf.readBoolean();server.execute(()->{if(!player.hasPermissionLevel(2))return;Identifier id=Identifier.tryParse(rawId);if(id==null)return;if(type==0&&Registries.BLOCK.containsId(id))BreakRulesConfig.setInteractiveAllowed(id,enabled);else if(type==1&&Registries.BLOCK.containsId(id))BreakRulesConfig.setAdventureBreakAllowed(id,enabled);else if(type==2&&Registries.ENTITY_TYPE.containsId(id))BreakRulesConfig.setInteractiveEntityAllowed(id,enabled);else return;sendSync(player);});});}public static void sendSync(ServerPlayerEntity player){Set<String>a=BreakRulesConfig.interactiveExceptionsSnapshot(),b=BreakRulesConfig.adventureBreakSnapshot(),e=BreakRulesConfig.interactiveEntityExceptionsSnapshot();PacketByteBuf out=PacketByteBufs.create();out.writeVarInt(a.size());for(String id:a)out.writeString(id,256);out.writeVarInt(b.size());for(String id:b)out.writeString(id,256);out.writeVarInt(e.size());for(String id:e)out.writeString(id,256);ServerPlayNetworking.send(player,SYNC,out);}}
